// ROUTAGE (suite) : une recherche vectorielle par requête reformulée (1 à 3), pour mieux couvrir la question
const cfg = $input.first().json;
const requetes = [...new Set((Array.isArray(cfg.requetes) && cfg.requetes.length ? cfg.requetes : [cfg.requete || cfg.questionOriginale]).map(r => String(r || '').trim()).filter(Boolean))].slice(0, 3);
return requetes.map(requete => ({ json: { requete } }));

// FILTRAGE : fusionne les résultats des requêtes, filtre souple sur les entités citées (aucune entité : on garde tout), puis classe en favorisant les passages qui contiennent les mots-clés de la question
const cfg = $('When Executed by Another Workflow').first().json;
const lignes = $input.all().map(i => i.json).filter(j => j.chunk_id !== undefined && j.chunk_id !== null);
if (!lignes.length) return [{ json: { vide: true } }];

// un chunk trouvé par plusieurs requêtes garde sa meilleure similarité
const parId = new Map();
for (const j of lignes) { const e = parId.get(j.chunk_id); if (!e || Number(j.similarity) > Number(e.similarity)) parId.set(j.chunk_id, j); }
const brut = [...parId.values()];

const norm = s => String(s || '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();
const noms = (cfg.entites || []).map(norm).filter(Boolean);
const motsCles = (cfg.mots_cles || []).map(norm).filter(Boolean);
const parle = (j, nom) => norm([j.content, j.contexte, (j.mots_cles || []).join(' '), (j.entites || []).join(' ')].join(' ')).includes(nom);

let retenus = brut;
if (noms.length) {
  const f = brut.filter(j => noms.some(n => parle(j, n)));
  if (f.length) retenus = f; // si le filtre ne laisse rien, on garde tout
}
const cle = j => Number(j.similarity) + 0.03 * motsCles.filter(m => parle(j, m)).length;
retenus = retenus.sort((a, b) => cle(b) - cle(a));

// Ce que voit le reranker : contexte, résumé et extrait complet
const apercu = j => ['Document : ' + j.titre + ' (extrait n°' + j.ordre + ')', 'Contexte : ' + j.contexte, 'Résumé : ' + j.resume, 'Extrait : ' + String(j.content || '')].join('\n');
const chunks = retenus.slice(0, 15).map((j, i) => ({ id: i + 1, titre: j.titre, ordre: j.ordre, collection: j.collection, texte: 'Document : ' + j.titre + ' (extrait n°' + j.ordre + ')\nContexte : ' + j.contexte + '\nEntité principale : ' + ((j.entites || [])[0] || '') + '\n\n' + j.content, apercu: apercu(j), entites: j.entites || [], mots_cles: j.mots_cles || [], contenu: j.content }));
// question autonome : la première requête reformulée (elle intègre l'historique pour une relance comme « résume »)
const question = (Array.isArray(cfg.requetes) && cfg.requetes[0]) || cfg.questionOriginale;
return [{ json: { vide: false, questionOriginale: cfg.questionOriginale, question, entites: cfg.entites || [], seuil: Number(cfg.seuil) || 6, chunks } }];

// RERANKING (suite) : associe les notes aux passages, garde les 5 meilleurs au-dessus du seuil ;
// question qui cite plusieurs entités : on garantit aussi le meilleur passage (score ≥ 4) de chacune
const { chunks, questionOriginale, entites, seuil } = $('Filtrage sur les entités').first().json;
const scores = ($input.first().json.output || {}).scores || [];
const note = new Map(scores.map(s => [Number(s.id), Number(s.score)]));
const norm = s => String(s || '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();
const parle = (c, nom) => norm([c.contenu, c.texte, (c.mots_cles || []).join(' '), (c.entites || []).join(' ')].join(' ')).includes(nom);

const classes = chunks.map(c => ({ ...c, score: note.get(c.id) ?? 0 })).sort((a, b) => b.score - a.score);
const retenus = classes.filter(c => c.score >= seuil).slice(0, 5);

const noms = (entites || []).map(norm).filter(Boolean);
if (noms.length > 1) {
  for (const nom of noms) {
    if (!retenus.some(c => parle(c, nom))) {
      const meilleur = classes.find(c => parle(c, nom) && c.score >= 4);
      if (meilleur) retenus.push(meilleur);
    }
  }
}

return [{ json: {
  vide: false,
  refus: retenus.length === 0,
  questionOriginale,
  meilleurScore: classes.length ? classes[0].score : 0,
  retenus: retenus.map(c => ({ titre: c.titre, extrait: c.ordre, collection: c.collection, score: c.score })),
  contexte: retenus.map(c => c.texte).join('\n\n---\n\n')
} }];
